// Поднимаем темп до 142 BPM — золотой стандарт злого биг-бита 90-х
setcps(142/60/4)

stack(
  // 1. Основной рвущийся рифф: синкопы, скачки на октаву и короткие «плевки»
  note("<[e1 ~ e1 g1 ~ e1 a1 bb1] [e1 ~ e1 g1 ~ d2 c2 bb1] [e1 ~ e1 g1 ~ e1 a1 bb1] [g1 e1 g1 a1 bb1 a1 g1 d1]>")
    .s("sawtooth")
    // Резкая атака и короткий спад на каждую ноту, чтобы рифф «кусался»
    .decay(0.14).sustain(0.2)
    // Агрессивный резонансный фильтр, который открывается и закрывается на каждом такте
    .lpf(perlin.range(600, 3800).fast(2))
    .lpq(14)
    .distort(0.85)
    .crush(5)
    .gain(0.95),

  // 2. Дублирующий суб-бас на октаву ниже для «мяса» и давления в грудь
  note("<[e0 ~ e0 g0 ~ e0 a0 bb0] [e0 ~ e0 g0 ~ d1 c1 bb0]>")
    .s("square")
    .lpf(280)
    .distort(0.5)
    .gain(0.9),

  // 3. Злой ломаный бит с акцентом на снейр (в стиле Breathe / Smack My Bitch Up)
  s("[bd ~ ~ bd ~ bd ~ ~, ~ ~ sd ~ ~ ~ sd [~ sd]]")
    .bank("RolandTR909")
    .distort(0.6)
    .crush(7)
    .gain(1.15),

  // 4. Бешеные 16-е хэты с акцентами — именно они дают ощущение скорости вперед
  s("hh*16")
    .bank("RolandTR909")
    .gain("[0.4 0.2 0.8 0.2]*4")
    .hpf(4000)
    .distort(0.3),

  // 5. Тревожный индустриальный визг / сирена на заднем плане раз в 2 такта
  note("<~ [e4 ~ ~ ~ ~ ~ ~ ~] ~ [f4 e4 ~ ~ ~ ~ ~ ~]>")
    .s("sawtooth")
    .lpf(2500)
    .distort(0.9)
    .delay(0.375)
    .delayfeedback(0.5)
    .room(0.6)
    .gain(0.35)
)